<?php
/**
 * Antalya POS Menu Category Delete Handler
 *
 * @package Antalya_POS
 * @since 6.4
 */

if (!defined('ABSPATH')) {
    exit;
}

if (isset($_GET['del_cat'])) {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have sufficient permissions to perform this action.', 'antalya-pos'));
    }

    $cat_id = intval($_GET['del_cat']);
    if ($cat_id > 0) {
        // Verify CSRF nonce generated by wp_nonce_url() in category-list.php & category-view.php
        check_admin_referer('rtpos_delete_cat_' . $cat_id);

        global $wpdb;
        $t_cats    = $wpdb->prefix . 'rtpos_categories';
        $svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

        $deleted = $wpdb->delete(
            $t_cats,
            ['id' => $cat_id],
            ['%d']
        );

        if ($deleted !== false) {
            echo '<div class="apos-alert cat-alert-flex">' . $svg_check . '<span>' . sprintf(
                /* translators: %d: category ID */
                esc_html__('Category #%d deleted successfully!', 'antalya-pos'),
                $cat_id
            ) . '</span></div>';
        }
    }
}